function IS_INTERLEAVED(d, d', points, eps, scales):
  for t in scales:
    A  <- { (x,y) : d (x,y)  <= t       }
    B  <- { (x,y) : d'(x,y)  <= t + eps  }
    C  <- { (x,y) : d'(x,y)  <= t       }
    D  <- { (x,y) : d (x,y)  <= t + eps  }
    if not (A subset B) or not (C subset D):
      return False
  return True

