function INTERLEAVING_DISTANCE(d, d', points, eps_grid, scales):
  sort eps_grid ascending
  lo, hi <- 0, len(eps_grid) - 1
  # monotone predicate: binary search for first True
  if not IS_INTERLEAVED(d, d', points, eps_grid[hi], scales):
      return +infinity
  while lo < hi:
      mid <- (lo + hi) // 2
      if IS_INTERLEAVED(d, d', points, eps_grid[mid], scales):
          hi <- mid
      else:
          lo <- mid + 1
  return eps_grid[lo]

