from typing import Dict, List, Tuple

Edge = Tuple[int, int]
Dissimilarity = Dict[Edge, float]

def interleaving_distance(d: Dissimilarity, d2: Dissimilarity,
                          points: List[int], eps_grid: List[float],
                          scales: List[float]) -> float:
    grid = sorted(eps_grid)
    if not grid or not is_interleaved(d, d2, points, grid[-1], scales):
        return float('inf')
    lo, hi = 0, len(grid) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if is_interleaved(d, d2, points, grid[mid], scales):
            hi = mid
        else:
            lo = mid + 1
    return grid[lo]

def trop_mul(a: float, b: float) -> float:
    """Tropical multiplication = ordinary addition (shifts compose)."""
    return a + b

def trop_add(a: float, b: float) -> float:
    """Tropical addition = minimum (optimal interleaving)."""
    return min(a, b)

def tropical_compose(eps: float, delta: float) -> float:
    """Compose an eps- and a delta-interleaving: shift = eps (x)_trop delta."""
    assert eps >= 0 and delta >= 0
    return trop_mul(eps, delta)
